window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e3cb5a9422076afe"]={"versions": [{"id": "FIG-e3cb5a9422076afe", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd E2E Transmission manager</code>) zur Veranschaulichung des senderseitigen Zusammenspiels zwischen Software-Components (SWCs), der AUTOSAR-Runtime Environment (RTE) und der E2E-Protection über einen E2E-Transmission-Manager im Kontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SWC1</code>: Quell-Software-Component für das Datum <code>data1</code>.</li>\n<li><code>SWC2</code>: Quell-Software-Component für das Datum <code>data2</code>.</li>\n<li><code>RTE</code>: Laufzeitumgebung, fungiert als Kommunikationsvermittler zwischen den Komponenten.</li>\n<li><code>«transmission...» SWC3</code>: Transmission Manager Software-Component, die eingehende Datenelemente aggregiert, transformiert und über E2E abgesichert weiterleitet.</li>\n<li><code>E2E</code>: End-to-End-Schutzmechanismus / E2E-Wrapper-Funktionalität (<code>E2EPW</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Sender/Receiver-Kommunikation über Standard-RTE-APIs: <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>E2E-Wrapper-Aufruf: <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>Interne Logik: <code>Merge, selection and conversion of data elements(data1, data2) :data</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der synchrone bzw. asynchrone Kommunikationsablauf gliedert sich in folgende Schritte:</p>\n<ol class=\"fig-list\">\n<li><code>SWC1</code> und <code>SWC2</code> senden unabhängig voneinander ihre Nutzdaten via <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> bzw. <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> an die <code>RTE</code>.</li>\n<li>Die Transmission-Manager-Komponente <code>SWC3</code> liest die Daten über Aufrufe von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> aus der <code>RTE</code>.</li>\n<li>In einer internen Ausführungsphase aggregiert und transformiert <code>SWC3</code> die Eingangswerte (<code>Merge, selection and conversion of data elements(data1, data2) :data</code>).</li>\n<li><code>SWC3</code> übergibt das resultierende Gesamtdatum <code>data3</code> an den E2E-Schutz über <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>, welcher die E2E-Absicherung (z. B. CRC- und Counter-Berechnung) durchführt.</li>\n<li>Das abgesicherte Datum <code>data3</code> wird über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an die <code>RTE</code> zur Weiterleitung an den Kommunikationsstapel übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als exemplarisches Architekturmuster (Transmission Manager Pattern) für Architekturen, in denen Daten mehrerer SWCs zu einer gemeinsamen E2E-geschützten Nachricht zusammengeführt werden müssen. Die Verwendung von <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;</code> verdeutlicht die Einbindung von E2E-Protection-Wrappern um die RTE-Schreibaufrufe. Entwickler müssen sicherstellen, dass Konsistenz, Aktualität und Task-Scheduling der beteiligten SWCs aufeinander abgestimmt sind.</p>"}, {"id": "FIG-290231ec0f448649", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung des senderseitigen Zusammenspiels zwischen Software-Components (SWCs), der AUTOSAR-Runtime Environment (RTE) und der E2E-Protection über einen E2E-Transmission-Manager im Kontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SWC1</code>: Quell-Software-Component für das Datum <code>data1</code>.</li>\n<li><code>SWC2</code>: Quell-Software-Component für das Datum <code>data2</code>.</li>\n<li><code>RTE</code>: Laufzeitumgebung, fungiert als Kommunikationsvermittler zwischen den Komponenten.</li>\n<li><code>«transmission...» SWC3</code>: Transmission Manager Software-Component, die eingehende Datenelemente aggregiert, transformiert und über E2E abgesichert weiterleitet.</li>\n<li><code>E2E</code>: End-to-End-Schutzmechanismus / E2E-Wrapper-Funktionalität (<code>E2EPW</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Sender/Receiver-Kommunikation über Standard-RTE-APIs: <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>E2E-Wrapper-Aufruf: <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>Interne Logik: <code>Merge, selection and conversion of data elements(data1, data2) :data</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der synchrone bzw. asynchrone Kommunikationsablauf gliedert sich in folgende Schritte:</p>\n<ol class=\"fig-list\">\n<li><code>SWC1</code> und <code>SWC2</code> senden unabhängig voneinander ihre Nutzdaten via <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> bzw. <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> an die <code>RTE</code>.</li>\n<li>Die Transmission-Manager-Komponente <code>SWC3</code> liest die Daten über Aufrufe von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> aus der <code>RTE</code>.</li>\n<li>In einer internen Ausführungsphase aggregiert und transformiert <code>SWC3</code> die Eingangswerte (<code>Merge, selection and conversion of data elements(data1, data2) :data</code>).</li>\n<li><code>SWC3</code> übergibt das resultierende Gesamtdatum <code>data3</code> an den E2E-Schutz über <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>, welcher die E2E-Absicherung (z. B. CRC- und Counter-Berechnung) durchführt.</li>\n<li>Das abgesicherte Datum <code>data3</code> wird über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an die <code>RTE</code> zur Weiterleitung an den Kommunikationsstapel übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als exemplarisches Architekturmuster (Transmission Manager Pattern) für Architekturen, in denen Daten mehrerer SWCs zu einer gemeinsamen E2E-geschützten Nachricht zusammengeführt werden müssen. Die Verwendung von <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;</code> verdeutlicht die Einbindung von E2E-Protection-Wrappern um die RTE-Schreibaufrufe. Entwickler müssen sicherstellen, dass Konsistenz, Aktualität und Task-Scheduling der beteiligten SWCs aufeinander abgestimmt sind.</p>"}, {"id": "FIG-c9b763097ee61627", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung des senderseitigen Zusammenspiels zwischen Software-Components (SWCs), der AUTOSAR-Runtime Environment (RTE) und der E2E-Protection über einen E2E-Transmission-Manager im Kontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SWC1</code>: Quell-Software-Component für das Datum <code>data1</code>.</li>\n<li><code>SWC2</code>: Quell-Software-Component für das Datum <code>data2</code>.</li>\n<li><code>RTE</code>: Laufzeitumgebung, fungiert als Kommunikationsvermittler zwischen den Komponenten.</li>\n<li><code>«transmission...» SWC3</code>: Transmission Manager Software-Component, die eingehende Datenelemente aggregiert, transformiert und über E2E abgesichert weiterleitet.</li>\n<li><code>E2E</code>: End-to-End-Schutzmechanismus / E2E-Wrapper-Funktionalität (<code>E2EPW</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Sender/Receiver-Kommunikation über Standard-RTE-APIs: <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>E2E-Wrapper-Aufruf: <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>Interne Logik: <code>Merge, selection and conversion of data elements(data1, data2) :data</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der synchrone bzw. asynchrone Kommunikationsablauf gliedert sich in folgende Schritte:</p>\n<ol class=\"fig-list\">\n<li><code>SWC1</code> und <code>SWC2</code> senden unabhängig voneinander ihre Nutzdaten via <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> bzw. <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> an die <code>RTE</code>.</li>\n<li>Die Transmission-Manager-Komponente <code>SWC3</code> liest die Daten über Aufrufe von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> aus der <code>RTE</code>.</li>\n<li>In einer internen Ausführungsphase aggregiert und transformiert <code>SWC3</code> die Eingangswerte (<code>Merge, selection and conversion of data elements(data1, data2) :data</code>).</li>\n<li><code>SWC3</code> übergibt das resultierende Gesamtdatum <code>data3</code> an den E2E-Schutz über <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>, welcher die E2E-Absicherung (z. B. CRC- und Counter-Berechnung) durchführt.</li>\n<li>Das abgesicherte Datum <code>data3</code> wird über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an die <code>RTE</code> zur Weiterleitung an den Kommunikationsstapel übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als exemplarisches Architekturmuster (Transmission Manager Pattern) für Architekturen, in denen Daten mehrerer SWCs zu einer gemeinsamen E2E-geschützten Nachricht zusammengeführt werden müssen. Die Verwendung von <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;</code> verdeutlicht die Einbindung von E2E-Protection-Wrappern um die RTE-Schreibaufrufe. Entwickler müssen sicherstellen, dass Konsistenz, Aktualität und Task-Scheduling der beteiligten SWCs aufeinander abgestimmt sind.</p>"}, {"id": "FIG-001b9b9bd50cea19", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Veranschaulichung des senderseitigen Zusammenspiels zwischen Software-Components (SWCs), der AUTOSAR-Runtime Environment (RTE) und der E2E-Protection über einen E2E-Transmission-Manager im Kontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>SWC1</code>: Quell-Software-Component für das Datum <code>data1</code>.</li>\n<li><code>SWC2</code>: Quell-Software-Component für das Datum <code>data2</code>.</li>\n<li><code>RTE</code>: Laufzeitumgebung, fungiert als Kommunikationsvermittler zwischen den Komponenten.</li>\n<li><code>«transmission...» SWC3</code>: Transmission Manager Software-Component, die eingehende Datenelemente aggregiert, transformiert und über E2E abgesichert weiterleitet.</li>\n<li><code>E2E</code>: End-to-End-Schutzmechanismus / E2E-Wrapper-Funktionalität (<code>E2EPW</code>).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li>Sender/Receiver-Kommunikation über Standard-RTE-APIs: <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>, <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>E2E-Wrapper-Aufruf: <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>.</li>\n<li>Interne Logik: <code>Merge, selection and conversion of data elements(data1, data2) :data</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der synchrone bzw. asynchrone Kommunikationsablauf gliedert sich in folgende Schritte:</p>\n<ol class=\"fig-list\">\n<li><code>SWC1</code> und <code>SWC2</code> senden unabhängig voneinander ihre Nutzdaten via <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> bzw. <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> an die <code>RTE</code>.</li>\n<li>Die Transmission-Manager-Komponente <code>SWC3</code> liest die Daten über Aufrufe von <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> aus der <code>RTE</code>.</li>\n<li>In einer internen Ausführungsphase aggregiert und transformiert <code>SWC3</code> die Eingangswerte (<code>Merge, selection and conversion of data elements(data1, data2) :data</code>).</li>\n<li><code>SWC3</code> übergibt das resultierende Gesamtdatum <code>data3</code> an den E2E-Schutz über <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>, welcher die E2E-Absicherung (z. B. CRC- und Counter-Berechnung) durchführt.</li>\n<li>Das abgesicherte Datum <code>data3</code> wird über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an die <code>RTE</code> zur Weiterleitung an den Kommunikationsstapel übergeben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm dient als exemplarisches Architekturmuster (Transmission Manager Pattern) für Architekturen, in denen Daten mehrerer SWCs zu einer gemeinsamen E2E-geschützten Nachricht zusammengeführt werden müssen. Die Verwendung von <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;</code> verdeutlicht die Einbindung von E2E-Protection-Wrappern um die RTE-Schreibaufrufe. Entwickler müssen sicherstellen, dass Konsistenz, Aktualität und Task-Scheduling der beteiligten SWCs aufeinander abgestimmt sind.</p>"}], "trans": [{"from": "FIG-e3cb5a9422076afe", "to": "FIG-290231ec0f448649", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Rahmenelement: Der UML-Interaktionsrahmen mit dem Bezeichner <code>sd E2E Transmission manager</code> wurde entfernt.</li>\n<li>Beschriftung: Der Text des internen Funktionsaufrufs an SWC3 wurde am rechten Rand leicht verkürzt dargestellt (<code>Merge, selection and conversion data elements(data1, data2) :da</code>).</li>\n</ul>"}, {"from": "FIG-290231ec0f448649", "to": "FIG-c9b763097ee61627", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c9b763097ee61627", "to": "FIG-001b9b9bd50cea19", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
